	title 'QD Slab Patch        GS ROM 2 Patch'******************************************************************              Patches to QD for ROM 2** Copyright 1987-1992 Apple Computer, Inc.* All Rights Reserved******************************************************************* System Disk 2.0** 09 May 87     Steven Glass** 2/24/89	Mensch* Added fastfont load to startup** 14 Apr 89	STeven Glass** A number of additions were made to make the overhead speed* ups work in the PATCH.  Additional code was added to the* startup routine patch as well as InitPort and OpenPort.** A number of routines were patched for the first time.* Many of these routines dirty some bits on direct page and* jump back into rom.** The other routines that take advantage of or set clear* the dirty bits, are from the rom source and are linked in.** 13 May 89	Steven Glass** Added code to hit dirty bits on PPToPort, PaintPixels and* ScrollRect.** Added code to install the patch to SetDrawMask.  This was inadvertantly* left out last time.** 31 May 89	Mensch** OrigSetGrafProcs had wrong address. (This caused printing not* to work on old ROMs)** 01 Jun 89	Steven Glass** Patched 10 internal vectors used by polygons and other routines.** 12/5/89	Mensch* Patched the shutdown routine so that it frees up shadowed memory** 24-Sep-90	Dave Lyons** Version $8306.* Added Get640Colors and Set640Color.  (The Menu and Window* mgrs each had their own copy of the 640-color table, and* so do a lot of applications and DAs.  Makes more sense to* have one copy here in QD.)** 25-Sep-90	Dave Lyons** Removed check of BigMachine--we always use FastFont now,* without checking the machine size.** 22-Oct-90	Dave Lyons** Added $DC04 GetScanlineAddr.** 20-Nov-90	Dave Lyons** Added ClearScreen patch that clears the correct bank (was* previously clearing bank $E1 even if we got shadowing).* Patch also checks the DontClearScreen flag that we can set* in the QDStartUp patch.** 21-Nov-90	Dave Lyons** Changed DontClearScreen logic so that if you set bit $0100* in the MasterSCB, we still clear the screen if it wasn't* already turned on.** 25-Nov-90	Dave Lyons** Changed version to $8307, since 5.0.4 is going to be $0306.** 14-Feb-91	Dave Lyons** Removed GetScanlineAddress.** 25-Feb-91	Dave Lyons** QDStartUp now deletes Message #6 (the mouse position message)* from the MessageCenter if the screen was off.  It only makes* sense to preserve the mouse position on a true smooth launch.** 7-Apr-91	Dave Lyons** QDShutDown now shuts down QDAux first if it's started up (this* is necessary because Standard File now starts up QD Aux).** 5-Aug-91	Dave Lyons** Messed with SetCursor patch to allow flickerless cursors by* setting bit 31 of the cursor pointer when the mask is* unchanged.** 26-Aug-91	Dave Lyons** QDStartUp leaves the MasterSCB $0100 (smooth launch) bit set* until the call is done, so that CloseView can see the bit* during its ClearScreen patch.** 6-Sep-91	Dave Lyons** QDShutDown now turns off linearization ($C029 bit 6) even* if it leaves the SHR screen on.  It's evil to leave linear* on, because it screws up double-hires!** 19-Nov-91	Dave Lyons** QDShutDown inits the SCBs and color table 0.** QDStartUp checks bit 2 of BRAM $5F to disable scanline interrupt* use (for better compatibility with accelerators and VOCs).** 27-Nov-91	Dave Lyons** Patched InflateTextBuffer to return errors.** 3-Dec-91	Dave Lyons** Finished fixing above--on failure, it needs to restore a few direct page* locations, so we don't think the buffer has been inflated when it hasn't.* (Since QuickDraw Aux chains in *after* the main QD buffer-resize routines,* QD already decided it was okay to store the new buffer size values when* QD Aux found it could not resize its buffers, so we have to undo the damage.)** 3-Feb-91	Dave Lyons** Fix QDStartUp to cope with FastFont no longer being available* (the code change is in QD:FastFontCache, which we link in).** QDStartUp copies the $E1 screen down to the $01 screen if we* got shadowing.** 5-Feb-92	Dave Lyons** Version $0307 for 6.0 final.************************************************************************* 17-Feb-92	Dave Lyons** Version $8308 for 6.0.1d1.** 2-Apr-93 DAL** Version $0308 for 6.0.1.**********************************************************************************************************************************			   **              Copyright (C) 1985-1993		   **              All Rights Reserved		   **              Apple Computer, Inc.		   **			   *****************************************************************TheQDVersionNum	equ $0308	;2-Apr-93 DAL	export SystemFont:equSystemFont	equ $FE77E0NoFastFontMask	equ $1000	include 'all.macros'	include ':::sys.equs.asm'	INCLUDE ':::qd:QDEquates:qd.data.asm'	INCLUDE ':::qd:QDEquates:core.globals1'	INCLUDE ':::qd:QDEquates:core.globals2'	include 'e16.memory'	MACRO	bcsl &A	bcc  @dontTake	brl  &A@dontTake	MEND* The following macro should be used by any routine that changes the zeropage pattern* holder, the penpat or the back pat...	MACRO	DirtyPatterns	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #AllPatsBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND	MACRO	DirtyPort	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #PortBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND	MACRO	DirtyMask	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #PenMaskBad	; turn off both patterns	sta <DirtyDPFlags,x	MEND	MACRO	DirtyDrawState	ldx #512	; switch to qdDPage2	lda <DirtyDPFlags,x	; get the proper flags	and #DrawStateBad	; turn off both patterns	sta <DirtyDPFlags,x	MENDThisGimmeVersion	Proc Export	;	lda #TheQDVersionNum	rtl;-----------------------------------------------------------;; This is the code pointed to by the v_?Rgn and v_?Rect; vectors.;; It just stuffs the noun and jumps right in.;; Added 1 Jun 89	SEG	Export NewRgnCode	Export NewRectCodeNewRgnCode	lda #RgnNounGetOnDown	sta DrawNoun	jml CommonSlabSetupNewRectCode	lda #RectNoun	bra GetOnDown	ENDP	EJECT********************************************************************************OpenInitPort2	PROC Export** Description:	This patch is for both openport and initport. It will*	modify the port SCB after the whole port has been set up.**** Inputs:	PortPtr:Long** Outputs:	None** External Refs:** Entry Points:*** Change History** 14 Apr 89	Steven Glass** Hit the dirty flags for both calls so that the port appears dirty.********************************************************************************	DefineStackyetAnotherdPage	wordSaveDPage	wordRTL1	block 3RTL2	block 3thePort	longROMOpenPort	equ $FE12E4ROMInitPort	equ $FE1329	Export OpenPort2OpenPort2	phd	pha	tsc	tcd	pei <thePort+2	pei <thePort	lda <yetAnotherDPage	jsl ToROMOpenPort	bra common	Export InitPort2InitPort2	phd	pha	tsc	tcd	pei <thePort+2	pei <thePort	lda <yetAnotherDPage	jsl ToROMInitPortcommon;; Make the port really dirty.;	php		; save the status	pha		; save the error code if any	lda <yetAnotherDPage	phd		; save d-page	tcd		; set d-page to QD	DirtyPort		; do the dirty deed	pld		; restore d-page	pla		; get back error code	plp		; get back status; end check	bcs IOPortEnd	; if an error occured skip this code;; EXP place code here that will modify the grafport to point to shadowed RAM if that was; enabled!	ldy #3	; get the offset to the proper place	lda >$E0C035	; get the shadow register	and #$0008	; test the shadowing flags!	bne ShadowOff	; if zero, then shadowing is on	lda #$0120	;	sta [thePort],y	; and change the port referenceShadowOff	lda #00;; EXP EndIOPortEnd	tax	ldy #4	pla	pld	jml ToStripToROMOpenPort	jsl ROMOpenPort	rtlToROMInitPort	jsl ROMInitPort	rtl	EndP	EJECT*** old way	********************************************************************************** old way	**** old way	QDShutDown2	PROC Export*** old way	**** old way	* Description:	This is a post-patch for the qd-shutdown call that will*** old way	*	disable shadowing if enabled.*** old way	**** old way	**** old way	* Inputs:	None*** old way	**** old way	* Outputs:	None*** old way	**** old way	* External Refs:*** old way	**** old way	* Entry Points:*** old way	**** old way	********************************************************************************** old way*** old way	ROMShutDown	equ $FE0BE0	; address of ROM based routine... (removed 19-Nov-90 DAL)*** old way*** old way		cmp #0*** old way		beq @Ooops*** old way*** old way		phd*** old way		phy*** old way		phx*** old way		pha*** old way*** old way		tcd*** old way*** old way	***	lda >BigMachine*** old way	***	beq @NotBig*** old way*** old way*** old way		PushWord #2*** old way		ldx #512*** old way		lda FastRomFont+2,x*** old way		and #$00FF*** old way		pha*** old way		lda FastRomFont,x*** old way		pha*** old way		_SetPurge*** old way*** old way*** old way	*** @NotBig*** old way*** old way		pla*** old way		plx*** old way		ply*** old way		pld*** old way	@Ooops*** old way*** old way*** old way		JSL ToROMShutDown	; call the ROM based shutdown first...*** old way*** old way		php	; save the proc status*** old way		pha	; save the error code*** old way*** old way	;------------------------------------------------------*** old way	; Turn off shadowing for the SHR Screen*** old way	;*** old way	; 12/5/89 	Mensch*** old way	; Added code to dispose of the shadowed screen memory*** old way	;*** old way		sep #$20	; turn off long <A>*** old way		longA Off*** old way		lda >$E0C035	; get the shadow register*** old way		and #$0008	; test the shadowing flags!*** old way		bne ShadowOff	; if zero, then shadowing is on*** old way		lda >$E0C035	; load the shadow register*** old way		ora #$08	; set bit 3... (turn screen shadow off)*** old way		sta >$E0C035	; and resave it!*** old way		longA On	; now release the shadowed screen area*** old way		REP #$20*** old way		pha*** old way		pha*** old way		PushLong #$012000	; first find the handle that has that memory*** old way		_FindHandle*** old way		_DisposeHandle	; and dump it...*** old way		longA On*** old way	ShadowOff	REP #$20	; and turn back on long <A>*** old way*** old way		pla*** old way		plp*** old way		RTL*** old way*** old way	ToROMShutDown	jsl ROMShutDown*** old way		RTL********************************************************************************QDShutDown2	PROC Export** Description:	This patch makes QDShutDown more like ROM 3 and lets me*	mess with leaving the SHR screen turned on.** Inputs:	None** Outputs:	None** 19-Nov-90 DAL:  Sucked this code in from QD:Init.asm, routine CoreTerminate.********************************************************************************DisposeHandleGlue	equ $fe1110LclRTL	equ $fe0050	Macro&Lab	JSRL &Addr	GBLA &MacroCnt&MacroCnt	SETA &MacroCnt+1	phk	per theRTL&MacroCnt-1	pea |LclRTL-1	jml >&AddrtheRTL&MacroCnt	MEND* QDShutDown2	cmp #0	bne @Continue	jml >$feff8b	;oEndCall0@Continue	jsr QDStart2	;(RAM copy --DAL)*** added 7-Apr-91 DAL	pea 0	_QDAuxStatus	pla	beq @noQDAux	_QDAuxShutDown@noQDAux*** end of 7-Apr-91 DAL*** added 19-Nov-91 DAL -- fix up the color tables and SCBs	pha	_GetMasterSCB	pla	and #$FFF0	ora #$0080	pha	_SetMasterSCB	pushlong #$E19E00	_InitColorTable	pea $0080	_SetAllSCBs*** end 19-Nov-91	pea #2	; set the purge level to 2	ldx #512	; on the fastfont...	lda FastRomFont+2,x	and #$00FF	pha	lda FastRomFont,x	pha	_SetPurge** Deallocate rgn cache memory*	ldx #$02F4	lda 2,x	pha	lda 0,x	pha	jsl DisposeHandleGlue;-----------------------------------------------;; Close the first port and get rid of the memory; it is in.;	ldx #256	lda FirstPortHandle+2,x	pha	sta temp+2	lda FirstPortHandle,x	pha	sta temp	lda [temp]	tax	ldy #2	lda [temp],y	pha	phx	_ClosePort	jsl DisposeHandleGlue;-----------------------------------------------;; Get rid of text buffer;***	PushLong TextBufHandle	pei TextBufHandle+2	pei TextBufHandle	jsl DisposeHandleGlue;-----------------------------------------------;; Get rid of the buffer memory	pei BufferHandle+2	pei BufferHandle	jsl DisposeHandleGlue;-----------------------------------------------; Get rid of shadowed ram here; test for shadowing enabled, if it is, turn it off and; dispose of the screen...	sep #$20	; turn off long <A>	longA Off	lda >$E0C035	; load the shadow register	and #$08	; set bit 3... (turn screen shadow off)	bne @NotShadowed	longA On	REP #$20	; and turn back on long <A>	pha	pha	pea $0001	; find the shadowed screen memory	pea $2000	; handle, shadowing was on...	_FindHandle	_DisposeHandle	; and throw it the hell away..@NotShadowed	longA On	REP #$20;-----------------------------------------------;; Now get rid of screen memory.  Cannot	do a find; since we could be	called after a startup call; that was aborted because screen was already; owned.  We don't want to release someone; else's memory.;	ldx #256	lda ScreenHandle+2,x	pha	lda ScreenHandle,x	pha	jsl DisposeHandleGlue;-----------------------------------------------;; Get rid of the memory used by cursor save;	jsrl $fe3cad	;CursorShutDown;----------------------------------------------------;; Turn off graphics	and linearization in bank 1/E1;;	pha	;added 19-Nov-90 DAL;	_GetMasterSCB	;added 19-Nov-90 DAL;	pla	;added 19-Nov-90 DAL;	and #$0100	;added 19-Nov-90 DAL;	bne @1	;added 19-Nov-90 DAL;;	sep #$30	; go to 8 bit mode;	longa off;	longi off;	lda >NewVideo;	and #%00111111	; turn off graphics	and linearization;	sta >NewVideo;	rep #$30	; go back to 16;	longi on;	longa on;@1		;added 19-Nov-90 DAL*** added 6-Sep-91 DAL -- turn off linearization, or SHR+linearization	pha	_GetMasterSCB	pla	ldx #%00111111	and #$0100	;bit 8 = leave SHR screen showing!	beq @1	;turn off both	ldx #%10111111	;turn off linear, leave screen on@1	txa	sep #$30	and >NewVideo	sta >NewVideo	rep #$30*** end of 6-Sep-91 DAL;-----------------------------------------------;; Clear the entry in the WAPT;	lda #0	; not a user call (seed the a-reg	pha	; to save bytes below	PushWord #TSNumber	; Put TSNum on stack	pha	; new value is zero	as set above.	pha	_SetWAP;------------------------------------------------------; Turn off shadowing for the SHR Screen;	sep #$20	; turn off long <A>	longA Off	lda >$E0C035	; load the shadow register	ora #$08	; set bit 3... (turn screen shadow off)	sta >$E0C035	; and resave it!	longA On	REP #$20	; and turn back on long <A>	jml >$feff3f	EndP******************************************************************* QDStartup**     ZPToUse*     MasterSCB*     MaxWidth*     UserID** Fixes the handle to the cursor save area so it does not* cross bank boundries.** Modification History** 22 May 87    SEG** This routine is similar to the one that patches ROM1 but does not* have to deal with	the scan line interrupt vector.** 2/24/89	Mensch* Add fastfont loading...** 08 Mar 89	Steven Glass** Dispose orig port allocated by the rom and allocated a new* one as fixed so it will be in low rather than high memory.** 14 Apr 89	Steven Glass** Changed the way dirty flags were intitialized so that* Applications can use bit 14 to indicate that they want the* shortcuts used.** 20-Nov-90+	Dave Lyons* See top of file.******************************************************************QDStartup2	PROC EXPORT	import UpdateCursor	import RefreshCursor	import DontClearScrnFlag	;20-Nov-90 DAL	DefineStackOrigD	wordRTL1	block 3RTL2	block 3uUserID	worduMaxWidth	worduMasterSCB	worduZPToUse	word	tax	; save the incoming	WAP in X	phd	tsc	tcd*** added 20-Nov-90 DAL	lda <uMasterSCB	and #$0100	sta >DontClearScrnFlag	lda >$E0C029	and #$0080	bne @1	sta >DontClearScrnFlag*** added 25-Feb-91 DAL: If the screen was off, kill the Event Manager mouse pos message	phx	pea 3	;delete message	pea 6	;message type	pha	pha	;handle (ignored)	_MessageCenter	plx*** end of 25-Feb-91 DAL@1;;;	lda #$0100	;removed 26-Aug-91 DAL;;;	trb <uMasterSCB	;removed 26-Aug-91 DAL*** end of 20-Nov-90 DAL	pei uZPToUse	; push inputs onto stack again	pei uMasterSCB	pei uMaxWidth	pei uUserIDRomStartup	equ $FE0A91;----------------------------------------------------------;; If QD is already active, then skip this.;	txa	jsl OffToRom*** added 20-Nov-90 DAL	pha	lda #0	sta >DontClearScrnFlag	pla*** end of 20-Nov-90 DAL	bcsl error*** added 26-Aug-91 DAL -- clear MasterSCB $0100 here	pha	_GetMasterSCB	pla	and #$FEFF	pha	_SetMasterSCB*** end 26-Aug-91 DAL*** added 19-Nov-91 DAL -- check BRAM to disable scanline interrupt use	pha	pea $005F	_ReadBParam	pla	and #$0004	;bit 2 = no scanline ints	beq @normal	pea 0	_SetIntUse@normal*** end 19-Nov-91	lda uZPToUse	tcd;; EXP 1/25/89 see if we can allocate the shadowed screen, if so, do it!; EXPERIMENT 1 aprox 10% speed increase	ldx #512	; switch to qd dpage 2	lda MasterSCB	; get the passed flags from the top of MasterSCB	and #$4000	; strip off the high bit 14 ...	beq @NoDirty	lda #$8000@NoDirty	sta <DirtyDPFlags,x	; and save this value...	lda MasterSCB	; get the passed flags from the top of MasterSCB	bpl EXP0020	; if negative clear, no shadowing!	pha	; space for handl	pha	PushLong #$8000	; size of screen	pei UserID	PushWord #$C002	; fixed location, locked	pea $0001	pea $2000	jsl NewHandleGlue	pla	; discard this handle for now...	plx	bcs EXP0010	; if an error, then we didn't allocate Shadow screen*** added 3-Feb-92 DAL -- copy E1 screen down to 01 screen if we got shadowing	ldx #$2000	pea $00e1	phx	;src = $e1/2000	pea $0001	phx	;dest = $01/2000	pea 0	pea $7d00	_BlockMove*** end 3-Feb-92; If we get this far, we have allocated a shadowed screen and we should now set; the shadowing bit on for the SHR screen.	sep #$20	; turn off long <A>	longA Off	lda >$E0C035	; load the shadow register	and #$F7	; reset bit 3...	sta >$E0C035	; and resave it!	longA On	REP #$20	; and turn back on long <A>	bra EXP0020EXP0010; Shadowing didn't get allocated, lets change our bitflags here	lda MasterSCB;;;	and #$7FFF	; strip off the shadow flag*** opt 3-Feb-92 DAL -- save a stoopid byte	asl a	lsr a*** end 3-Feb-92	sta MasterSCB	; to indicate we are not using shadowing.EXP0020; END;; Install the fast font if this is a big machine and their font; is available.;***	lda >BigMachine	;removed 25-Sep-90 DAL***	beq NoFastFont	lda MasterSCB	; get the passed flags from the top of MasterSCB	and #NoFastFontMask	; strip off the high bit 14 ...	bne NoFastFont	; if that bit is set then don't load the fast font...;; Now install the fastfont stuff if we got enough memory	Import DoFastSetup	tdc	pha	pha	jsl DoFastSetup	pla	ply	bcs NoFastFont	ldx #512	sta FastRomFont,x	sty FastRomFont+2,x	phy	pha	_SetSysFont	; now set the system fontNoFastFont;; The old rom allocated the default port as locked rather than fixed,; so we kill that first handle and allocate a new one that is fixed.;; Note:  no error checking is done here.  The closeport, dispose, newhandle; and openport had all better work as promised.  If they don't the machine; ain't working well engough to return an error anyway.;; Start by closing the current port	pei PortRef+2	pei PortRef	_ClosePort; now dispose of the memory for that port.;	ldx #256	lda FirstPortHandle+2,x	pha	lda FirstPortHandle,x	pha	_DisposeHandle;; Get new memory for the port;	lda #0	pha	pha	pha	pea PortSize	; size of handle	pei UserID	; userid to use	pea #attrFixed	; attributes	pha	pha	jsl NewHandleGlue	pla	ply	ldx #256	sta FirstPortHandle,x	sty FirstPortHandle+2,x; Deref the handle and open the port;	sta PortRef	sty PortRef+2	ldy #2	lda [PortRef],y	pha	lda [PortRef]	pha	_OpenPort;; End change that allocates default port low instead of high;	jsl FixHandle2	PushWord #CurUpdateRefNum	; install pointer to update	PushLong #UpdateCursor 	; cursor routine	_SetVector	PushWord #ScanIntRefNum ; install pointer to	PushLong #RefreshCursor ; cursor refresh routine	_SetVectorError	tax	ldy #8	pld	jml ToStripOffToROM	jsl RomSTARTUP	rtl	ENDP****************************************************************** ClearScreen  (Color : integer);** Clears the super hi-res screen, setting all words to the* value passed.*** Modification History**  12 Feb 89    DDG	   This routine now checks for shadowing***  14 Feb 89    DDG	   Fixed a bug where I was reading the wrong*	   word on the stack for the color.** --------------* 20-Nov-90	Dave Lyons** Stole this from the ROM 3 source to patch ROM 1.  We need to* clear the bank 1 screen if we're shadowing.** Added check of DontClearScreenFlag for QDStartUp patch.*****************************************************************	EXPORT ClearScreenClearScreen	PROCOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3ParmColor	equ RTL2+3	jsr QDStart2	;RAM copy	lda >DontClearScrnFlag	bne @done	lda #0	sta >DontClearScrnFlag	tdc	jsl $fe3eaf	;HideCursor	phb	; save bank register	lda >$E0C035	; get the shadow register	and #$0008	; test the shadowing flags!	bne @1	; if zero, then shadowing is on	pea $0101	; push on the shadowed bank	bra @2@1	pea $E1E1	; push this on stack@2	plb	; set bank twice to	plb	; clear stack	lda ParmColor+1,s	ldx #160*200-2@Loop	sta $2000,x	dex	dex	bpl @Loop	plb	; get back bank address	tdc	; fake out tool locator call	jsl $fe3e87	;ShowCursor@done	jml $feff60	;BusyEC2	export DontClearScrnFlagDontClearScrnFlag	dc.w 0	EndP*****************************************************************SetCursor	proc Export** This patch checks the incoming WAP to see if QD is active.* If QD is not active, we just report an error and quit.** This patch is being made because two Activision Applications* made calls to this routine before starting QuickDraw.  These* Apps (DrawPlus and PaintWorks Plus) seemed to work fine* until appletalk was activated (god knows how it worked).** We discovered that activating Appletalk put different values* at page one in bank zero which is used by Cursor routines* if QD is not active.  Setting the cursor then trashed* random memory depending on what values were in* Page 1.*** Inputs:*	Pointer to Cursor record (on stack)** Outputs:*	none** External Refs:*	none** Entry Points:*	none*	longa on	; mode	longi on** Change History** 27 May 88	Steven Glass** Added today.*****************************************************************StartofZP	equ CursorSTARTUseInterrupts	equ StartofZPIntPending	equ UseInterrupts+2MouseY	equ IntPending+2MouseX	equ MouseY+2NextMouseY	equ MouseX+2NextMouseX	equ NextMouseY+2CurHeight	equ NextMouseX+2	; Num scan lines high of cursorCurWidth	equ CurHeight+2	; Num WORDS wide of	cursorCursorRect	equ CurWidth+2CursorY1	equ CursorRectCursorX1	equ CursorY1+2CursorY2	equ CursorX1+2CursorX2	equ CursorY2+2CursorMode	equ CursorX2+2CursorRecPtr	equ CursorMode+2CursorPtr	equ CursorRecPtr+4MaskPtr	equ CursorPtr+4CursorPtr1	equ MaskPtr+4MaskPtr1	equ CursorPtr1+4CursorPtr2	equ MaskPtr1+4MaskPtr2	equ CursorPtr2+4CursorPtr3	equ MaskPtr2+4MaskPtr3	equ CursorPtr3+4CursorPtr4	equ MaskPtr3+4MaskPtr4	equ CursorPtr4+4CursorPtr5	equ MaskPtr4+4MaskPtr5	equ CursorPtr5+4CursorPtr6	equ MaskPtr5+4MaskPtr6	equ CursorPtr6+4CursorPtr7	equ MaskPtr6+4MaskPtr7	equ CursorPtr7+4SaveHandle	equ MaskPtr7+4SavePtr	equ SaveHandle+4SaveSize	equ SavePtr+4CursorRef	equ SaveSize+2MaskRef	equ CursorRef+4HotSpot	equ MaskRef+4SaveRef	equ HotSpot+4ScreenRef	equ SaveRef+4CursorLevel	equ ScreenRef+2ObscureFlag	equ CursorLevel+2;	cmp #0	; is the a-reg zero	tax	bne @qdStarted	; we're active	ldy #4	ldx #NotInitialized	jml ToStrip@qdStarted;;;	jml $FE3D89*** Flickerless cursor stuff  5-Aug-91 DAL*** If bit 31 of SetCursor value is set, don't undraw old cursor,*** and don't let DrawCursor mess up SaveArea.ROMNotVisible	equ $FE3D9F	tay	lda 9,s	;high word of cursor ptr	tax	asl a	lsr a	sta 9,s	;cleared bit 31	tya	;A=preserved, X=high word of input	jsr LOCALQDStart	clc	adc #$100	tcd	php	; save processor	sei	; turn off interrupts to do this	bit <CursorLevel	bmi NotVisible	bit <ObscureFlag	bmi NotVisible	txa	bmi NoFlicker	tdc	jsl UnDrawCursor	; restore under cursorNotVisible	jml ROMNotVisibleNoFlicker	lda 10,s	;get pointer to cursor rec	sta CursorRecPtr	lda 10+2,s	;high word of new cursor rec	sta CursorRecPtr+2;	lda [CursorRecPtr]	; I move height and	width;	sta CurHeight	; to zero page;	ldy #2;	lda [CursorRecPtr],y;	sta CurWidth	lda CursorRecPtr	; point to cursor image	clc	adc #4	sta CursorPtr	lda CursorRecPtr+2	sta CursorPtr+2	lda SaveSize	; get savesize in a	sec	; get rid of extra word per line	sbc CurHeight	sec	sbc CurHeight	tay	; put copy in Y too	clc	adc CursorPtr	sta MaskPtr	lda CursorPtr+2	sta MaskPtr+2	lda [MaskPtr],y	; get hot spot	sta HotSpot	iny	iny	lda [MaskPtr],y	sta HotSpot+2;----------------------------------------------;; Update the appropriate pointers.;	lda SavePtr	; the first pointer	is savesize past	clc	; saveptr.	adc SaveSize	sta CursorPtr1	lda SavePtr+2	adc #0	sta CursorPtr1+2	ldx #0SetUpLoop	lda CursorPtr1,x	clc	adc SaveSize	sta CursorPtr1+4,x	lda CursorPtr1+2,x	adc #0	sta CursorPtr1+6,x	inx	inx	inx	inx	cpx #13*4	; 52, 7 sets of two	pointers	bcc SetUpLoop;----------------------------------------------;; Now I must shift the cursor and mask into; the appropriate places.;***	jsr ShiftStuff	;$FE3CE1 in ROM 1	phk	per @cont-1	pea $0050-1	;$FE0050 is an RTL in ROM 1	jml >$fe3ce1@cont;----------------------------------------------;; Now I can show the new cursor;	bit CursorLevel	bmi DoNotShow	bit ObscureFlag	; or should a set cursor unobscure it?	bmi DoNotShow*** This is really ugly and cruel.  Since there's already an old cursor on*** the screen, which I -don't- want to get stuffed into the SaveArea, I*** point SavePtr at the ROM around the call to DrawCursor.	pei <SavePtr+2	pei <SavePtr	lda #$fefe	sta <SavePtr+2	sta <SavePtr	jsl DrawCursor	pla	sta <SavePtr	pla	sta <SavePtr+2DoNotShow	plp	; restore interrupt	status	ldx #0	pld	ldy #4	jml $e10180	;ToBusyStrip	ENDP********************************************************* InflateTextBuffer (patched 27-Nov-91 DAL)** (Original is in QD:Text.asm.)********************************************************MyInflateTextBuffer	PROC exportOrigDirect	equ 1RTL1	equ OrigDirect+2RTL2	equ RTL1+3newHeight	equ RTL2+3newWidth	equ newHeight+2	jsr LocalQDStart	lda newWidth,s	sta <$56	;newFontWidth	lda newHeight,s	sta <$50	;newTBHeight*** added 3-Dec-91 DAL -- preserve old DP values that we may need to restore	ldx #256	lda <fontWidth,x	pha	pei <textBufHeight	pei <textBufRowWords*** end 3-Dec-91	jsl $fe6a8d	;InflateTB (ROM 1);;;	ldy #4;;;	jmp BusyEC*** added 3-Dec-91 DAL -- honor error code from InflateTB, and restore***  DP values if we had an error (even though QD doesn't mess up the***  values if it can't resize the buffer, we do mess them up if QD Aux***  can't resize -its- buffers).	tay	;error code to Y	pla	bcc @noStore1	sta <textBufRowWords@noStore1	pla	bcc @noStore2	sta <textBufHeight@noStore2	pla	bcc @noStore3	ldx #256	sta <fontWidth,x@noStore3	tyx	;error code to X	pld	ldy #4	jml $e10180	;ToBusyStrip*** end 3-Dec-91	EndP********************************************************* $DA04 Get640Colors():PatternTablePtr*                      LONG** Returns a pointer to a table of all the solid 640-* mode dithered patterns (32 bytes of $00, 32 bytes of* $11, ..., 32 bytes of $ff).** The Menu and Window Managers use this to avoid having* their own copies.** New call 24-Sep-90 DAL for System Software 6.0********************************************************Get640Colors	PROC	import SolidColors	lda #^SolidColors	sta 9,s	lda #SolidColors	sta 7,s	lda #0	clc	rtl	EndP********************************************************* $DB04  Set640Color(color)*                    WORD** New call 24-Sep-90 DAL for System Software 6.0********************************************************Set640Color	PROC	import SolidColors	lda 7,s	;input color number	and #$000f	xba	lsr a	lsr a	lsr a	adc #SolidColors	;carry is guaranteed clear	pea SolidColors>>16	pha	_SetPenPat	tax	;error code	ldy #2	;strip 2 bytes	jml $e10184	;ToStrip	EndPSolidColors	proc export dc.l $00000000,$00000000,$00000000,$00000000,$00000000,$00000000,$00000000,$00000000 dc.l $11111111,$11111111,$11111111,$11111111,$11111111,$11111111,$11111111,$11111111 dc.l $22222222,$22222222,$22222222,$22222222,$22222222,$22222222,$22222222,$22222222 dc.l $33333333,$33333333,$33333333,$33333333,$33333333,$33333333,$33333333,$33333333 dc.l $44444444,$44444444,$44444444,$44444444,$44444444,$44444444,$44444444,$44444444 dc.l $55555555,$55555555,$55555555,$55555555,$55555555,$55555555,$55555555,$55555555 dc.l $66666666,$66666666,$66666666,$66666666,$66666666,$66666666,$66666666,$66666666 dc.l $77777777,$77777777,$77777777,$77777777,$77777777,$77777777,$77777777,$77777777 dc.l $88888888,$88888888,$88888888,$88888888,$88888888,$88888888,$88888888,$88888888 dc.l $99999999,$99999999,$99999999,$99999999,$99999999,$99999999,$99999999,$99999999 dc.l $AAAAAAAA,$AAAAAAAA,$AAAAAAAA,$AAAAAAAA,$AAAAAAAA,$AAAAAAAA,$AAAAAAAA,$AAAAAAAA dc.l $BBBBBBBB,$BBBBBBBB,$BBBBBBBB,$BBBBBBBB,$BBBBBBBB,$BBBBBBBB,$BBBBBBBB,$BBBBBBBB dc.l $CCCCCCCC,$CCCCCCCC,$CCCCCCCC,$CCCCCCCC,$CCCCCCCC,$CCCCCCCC,$CCCCCCCC,$CCCCCCCC dc.l $DDDDDDDD,$DDDDDDDD,$DDDDDDDD,$DDDDDDDD,$DDDDDDDD,$DDDDDDDD,$DDDDDDDD,$DDDDDDDD dc.l $EEEEEEEE,$EEEEEEEE,$EEEEEEEE,$EEEEEEEE,$EEEEEEEE,$EEEEEEEE,$EEEEEEEE,$EEEEEEEE dc.l $FFFFFFFF,$FFFFFFFF,$FFFFFFFF,$FFFFFFFF,$FFFFFFFF,$FFFFFFFF,$FFFFFFFF,$FFFFFFFF	endp;*******************************************************;*;* $DC04 GetScanlineAddr(lineNum):@address;*                       WORD     PTR;*;* Returns a pointer to a scanline ($01xxxx or $E1xxxx).;*;* New call Dave Lyons 22-Oct-90 for System 6.0;*;*******************************************************;GetScanlineAddr	PROC;;	ldx #$0452	;anticipate badScanLine error;	lda 7,s;	cmp #200;	bcs @error;;	ldx #$00e1	;anticipate bank $E1 (no shadowing);	lda >$E0C035	;shadow;	and #$0008;	bne @bank;	ldx #$0001	;SHR shadowing;@bank	txa;	sta 11,s;;	lda 7,s;	asl a;	tax;	lda >$ffbd74,x;	sta 9,s;;	ldx #0;@error	ldy #2	;strip 2 bytes;	jml $e10184	;ToStrip;;;	EndP*****************************************************************QDCallTable2	PROC EXPORT** Call table for QD patch.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:	Export eSetPort	Export eSetPortLoc	Export eSetPortRect	Export eSetPortSize	Export eMovePortTo	Export eSetOrigin	Export eHidePen	Export eSetPenState	Export eSetDrawMask	Export ePenNormal	Export eSolidPenPat	Export eSolidBackPat	Export eSolidPattern	Export eSetGrafProcs	Export RectCalls	Export ePPToPort	Export eScrollRect	Export ePaintPixels*	longa on	; mode	longi on*** Change History** 14 Apr 89	Steven Glass** Added entry points to all calls now patched only for BigQD.* These include the rectangle drawing calls and the port* mainipulation calls that need to muck with the dirty bits.*******