******************************************************* QDStart** This is a local routine that increments the busy flag, saves* the current direct register on the stack and transfers* the a register to	the D register.** This is meant to be called at the start of any QD entry point* that requires zero page and the busy flag to be incremented.** In Doing this we trash the X-Register.  Hopefully this will* not cause anyone any problems.** We do know that A	and Y must be untouched.  Y for PortWord* and PortLong.  A for cursor routines that add $100 to A*****************************************************************QDStart2	proc Export	jsl IncBusyFlg	phd	; push d on stack	tcd	; set d	lda 3,s	; getorig rts	pha	; put on stack	lda 3,s	; move orig d to on	top of rts	sta 5,s	pla	; pull rts off stack	sta 1,s	; put over orig d	tdc	; get QD D back in a	rts	; done	ENDP*****************************************************************DirtyStuff	proc Export** This procedure has all the quickdraw calls that have* been patched to support the dirty flags.** These calls make something dirty and then jump* back into the ROM at 3 bytes past the orig entry.** We jump at plus 3 because we don't want to call QDStartup* twice.*** Inputs:*	none** Outputs:*	none** External Refs:*	none** Entry Points:	Export SetPort	Export SetPortLoc	Export SetPortRect	Export SetPortSize	Export MovePortTo	Export SetOrigin	Export HidePen	Export SetPenState	Export SetDrawMask	Export PenNormal	Export SolidPenPat	Export SolidBackPat	Export SolidPattern	Export SetGrafProcs	Export PPToPort	Export ScrollRect	Export PaintPixels*	longa on	; mode	longi on*****************************************************************OrigSetPort	equ $FE13DFOrigSetPortLoc	equ $FE13FEOrigSetPortRect	equ $FE1430OrigSetPortSize	equ $FE1472OrigMovePortTo	equ $FE148EOrigSetOrigin	equ $FE14B8OrigHidePen	equ $FE15C3OrigSetPenState	equ $FE161EOrigPenPat	equ $FE163FOrigSetDrawMask	equ $FE166DOrigBackPat	equ $FE1689OrigPenNormal	equ $FE174DOrigSolidPenPat	equ $FE165BOrigSolidBackPat	equ $FE16A5OrigSolidPattern	equ $FE16B7OrigSetGrafProcs	equ $FE17FCOrigPPToPort	equ $FE33F2OrigScrollRect	equ $FE3486OrigPaintPixels	equ $FE3682PPToPort	jsr LocalQDStart	DirtyPort	jml OrigPPToPort+3ScrollRect	jsr LocalQDStart	DirtyPort	jml OrigScrollRect+3PaintPixels	jsr LocalQDStart	DirtyPort	jml OrigPaintPixels+3SetPort	jsr LocalQDStart	DirtyPort	jml OrigSetPort+3SetPortLoc	jsr LocalQDStart	DirtyPort	jml OrigSetPortLoc+3SetPortRect	jsr LocalQDStart	DirtyPort	jml OrigSetPortRect+3SetPortSize	jsr LocalQDStart	DirtyPort	jml OrigSetPortSize+3MovePortTo	jsr LocalQDStart	DirtyPort	jml OrigMovePortTo+3SetOrigin	jsr LocalQDStart	DirtyPort	jml OrigSetOrigin+3HidePen	jsr LocalQDStart	DirtyDrawState	jml OrigHidePen+3SetPenState	jsr LocalQDStart	DirtyPort	jml OrigSetPenState+3SetDrawMask	jsr LocalQDStart	DirtyMask	jml OrigSetDrawMask+3PenNormal	jsr LocalQDStart	DirtyPort	jml OrigPenNormal+3SolidPenPat	jsr LocalQDStart	DirtyPatterns	jml OrigSolidPenPat+3SolidBackPat	jsr LocalQDStart	DirtyPatterns	jml OrigSolidBackPat+3SolidPattern	jsr LocalQDStart	DirtyPatterns	jml OrigSolidPattern+3SetGrafProcs	jsr LocalQDStartNoBusyFlag	; don't bump busy flag - Ben 7/30/90	DirtyPort	tdc		; restore a-reg	pld		; and d-reg	jml OrigSetGrafProcs	; this doesn't start with QDStart	Export LOCALQDStart	Export LOCALQDStartNoBusyFlagLOCALQDStart	pha	; inc busy flag	lda >BusyFlag	inc a	sta >BusyFlag	plaLOCALQDStartNoBusyFlag	; alt entry which doesn't inc busy flag	phd	; push d on stack	tcd	; set d	lda 3,s	; getorig rts	pha	; put on stack	lda 3,s	; move orig d to on	top of rts	sta 5,s	pla	; pull rts off stack	sta 1,s	; put over orig d	tdc	; get QD D back in a	rts	; done	ENDP	END